#include <algorithm>
#include <iostream>
#include <utility>
#include <vector>
using namespace std;

struct Entry {
    long long value;
    int pos;
};

pair<int, int> find_pair(vector<Entry> entries, long long target) {
    sort(entries.begin(), entries.end(), [](const Entry& first, const Entry& second) {
        return first.value < second.value;
    });
    int l = 0;
    int r = static_cast<int>(entries.size()) - 1;
    while (l < r) {
        long long sum = entries[l].value + entries[r].value;
        if (sum == target) {
            return {entries[l].pos, entries[r].pos};
        }
        if (sum < target) {
            ++l;
        } else {
            --r;
        }
    }
    return {-1, -1};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    long long target;
    cin >> size >> target;
    vector<Entry> entries(size);
    for (int i = 0; i < size; ++i) {
        cin >> entries[i].value;
        entries[i].pos = i + 1;
    }
    pair<int, int> answer = find_pair(entries, target);

    if (answer.first == -1) {
        cout << "IMPOSSIBLE\n";
    } else {
        cout << answer.first << ' ' << answer.second << '\n';
    }
    return 0;
}

